const emails = $input.all();
const summary = emails.map((item, i) => {
  const d = item.json;
  let from = 'unknown';
  if (d.from && typeof d.from === 'object' && d.from.text) {
    from = d.from.text;
  } else if (d.from && typeof d.from === 'string') {
    from = d.from;
  }
  const subject = d.subject || '(no subject)';
  const dateRaw = d.date || '';
  let dateStr = dateRaw;
  if (dateRaw) {
    try {
      const dt = new Date(dateRaw);
      if (!isNaN(dt.getTime())) {
        dateStr = dt.toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
      }
    } catch(e) {}
  }
  const snippet = (d.snippet || d.textPlain || '').substring(0, 120).replace(/\n/g, ' ');
  return { index: i + 1, from, subject, date: dateStr, snippet };
});
const lines = summary.map(e => '[' + e.index + '] ' + e.subject + '\n    From: ' + e.from + '\n    Date: ' + e.date + '\n    ' + e.snippet);
const text = '未読メール: ' + summary.length + '件\n\n' + lines.join('\n\n');
return [{ json: { count: summary.length, text: text, emails: summary } }];

